function searchDrugs(query, category = null, company = null) {
    let results = EGYPTIAN_DRUGS.filter(drug => {
        const matchesQuery = !query || 
            (drug.tradeName && drug.tradeName.toLowerCase().includes(query.toLowerCase())) ||
            (drug.scientificName && drug.scientificName.toLowerCase().includes(query.toLowerCase())) ||
            (drug.gtin && drug.gtin.includes(query));
        
        const matchesCategory = !category || drug.category === category;
        const matchesCompany = !company || drug.company === company;
        
        return matchesQuery && matchesCategory && matchesCompany;
    });
    
    return results.sort((a, b) => a.tradeName.localeCompare(b.tradeName));
}

function getDrugByGTIN(gtin) { return EGYPTIAN_DRUGS.find(drug => drug.gtin === gtin); }
function getDrugCategories() { return [...new Set(EGYPTIAN_DRUGS.map(d => d.category).filter(Boolean))].sort(); }
function getDrugCompanies() { return [...new Set(EGYPTIAN_DRUGS.map(d => d.company).filter(Boolean))].sort(); }

window.EGYPTIAN_DRUGS = EGYPTIAN_DRUGS;
window.searchDrugs = searchDrugs;
window.getDrugByGTIN = getDrugByGTIN;
window.getDrugCategories = getDrugCategories;
window.getDrugCompanies = getDrugCompanies;
